window.FILM_WORK_PROMPTS={"work_id":"src-078d1683967b319c","records":[{"work_id":"src-078d1683967b319c","frame_id":"FG-a59d478a7aa1489f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mid_90s_006.jpg","source_page":"https://film-grab.com/2019/11/08/mid90s/","scene":"昏暗卧室中央，一名穿深色T恤和牛仔裤的人物双手高举哑铃过头顶，呈站立姿态。背景可见床铺、书桌、办公椅及贴满海报和帽子的墙壁。","analysis":"画面采用平视视角，人物全身可见，位于画面中心偏右位置，占据约三分之一高度。环境占据大部分画面，左侧为书桌区域，右侧为床铺和健身器材。光线昏暗，主要光源来自左侧窗户，形成冷色调，室内细节处于阴影中，对比度较低，整体呈现颗粒感。","prompt":"昏暗的卧室室内场景，一名身穿深色印花T恤、蓝色牛仔裤和白色运动鞋的人物站在房间中央，双手高举黑色哑铃过头顶，呈站立姿态。人物脚下铺着带有黑白几何三角形图案的地毯。背景左侧有一张书桌和一把红黑配色的办公椅，窗户透入冷色光线。后方墙壁贴满各种海报，包括醒目的橙色Wu-Tang海报和右侧的大幅滑板海报。右侧墙面上挂着多顶棒球帽，旁边有床铺和健身器材。画面整体色调偏暗，带有明显的胶片颗粒感，光线对比柔和。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T05:28:49-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mid_90s_006.jpg","observed_dimensions":[1280,960],"source_thumbnail_dimensions":[500,375],"source_image_match_mae":0.493,"observed_resolution":"normal","observation_limits":[],"id":"VP-ac2c2a6fbfdab4d9","origin":"visual"},{"work_id":"src-078d1683967b319c","frame_id":"FG-7fe4242bbcfe78f5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mid_90s_017.jpg","source_page":"https://film-grab.com/2019/11/08/mid90s/","scene":"深色短发人物坐在深色皮沙发上，左手持打火机，右手夹着香烟凑近火苗，背景墙面贴有模糊海报。","analysis":"人物上半身占据画面主体，头部位于上方，双手在胸前操作。背景墙面及海报约占画面右侧三分之一，处于虚焦状态。光线昏暗，主要光源来自打火机火焰，照亮人物面部下半部及手部，整体色调偏暗，对比度低，呈现出一种压抑的视觉氛围。","prompt":"昏暗室内，深色短发人物身穿黑色T恤坐在深色皮沙发上，身体略微前倾。人物左手握着一个打火机，火苗向上燃烧，右手手指夹着一根白色香烟凑近火苗。面部表情平静，眼神向下注视。背景是贴满模糊海报和纸张的墙壁，处于失焦状态。画面整体色调偏暗，光线微弱，主要光源来自打火机的火光，照亮了人物面部和手部，营造出一种沉静、压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T05:28:56-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mid_90s_017.jpg","observed_dimensions":[1280,960],"source_thumbnail_dimensions":[500,375],"source_image_match_mae":0.467,"observed_resolution":"normal","observation_limits":[],"id":"VP-d22ac45074effaaa","origin":"visual"},{"work_id":"src-078d1683967b319c","frame_id":"FG-f33d7b06c0006794","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mid_90s_028.jpg","source_page":"https://film-grab.com/2019/11/08/mid90s/","scene":"昏暗室内，一名卷发人物面部占据画面中心，眼神向下凝视，背景几乎全黑，仅见肩部轮廓。","analysis":"构图极度紧凑，人物面部特写占据画面约80%面积，头顶与肩部边缘被裁切。视线略微向下，呈现俯视角度。光线极弱，仅微弱侧光勾勒鼻梁、颧骨及眼部轮廓，其余部分隐没在深重阴影中，色彩层次单一，仅存暗部暖调。","prompt":"极度昏暗的室内环境，画面主体为一名卷发人物的面部特写，占据画面绝大部分空间。人物眼神向下凝视，神情凝重，视线低垂。光线极其微弱，仅有一抹微弱的侧光勾勒出鼻梁、颧骨及眼部的轮廓，其余面部细节及背景均隐没在深沉的阴影中。人物肩部可见浅色衣物边缘，背景几乎全黑，无法辨识具体环境物体，整体色调压抑，仅存暗部暖调，营造出一种静谧而沉重的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T05:29:05-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mid_90s_028.jpg","observed_dimensions":[1280,960],"source_thumbnail_dimensions":[500,375],"source_image_match_mae":0.316,"observed_resolution":"normal","observation_limits":[],"id":"VP-b372b0be43dcaf01","origin":"visual"},{"work_id":"src-078d1683967b319c","frame_id":"FG-7aaca03dd841e783","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mid_90s_039.jpg","source_page":"https://film-grab.com/2019/11/08/mid90s/","scene":"昏暗环境中的人物面部特写，人物头部占据画面右侧，左侧为模糊暗色背景，整体色调偏黄褐，光线微弱。","analysis":"构图极度不对称，人物面部位于画面右半部分，左侧大面积留白为模糊背景。仅可见人物头部及少许肩部轮廓，身体大部分隐没在黑暗中。光线从左侧微弱投射，形成强烈的明暗对比，面部右侧陷入深重阴影，仅左侧眉眼和鼻梁有微弱高光，整体呈现低照度下的黄褐色调。","prompt":"极度昏暗的室内环境，画面右侧占据主导的是一名深色短发人物的面部特写。人物头部微微低垂，视线向下，神情凝重。光线极其微弱，仅从左侧照亮人物面部的左半部分，右脸完全隐没在浓重的黑色阴影中。画面左侧是大面积模糊的暗色背景，色调呈现深沉的黄褐色与黑色交织。人物肩部轮廓隐约可见，整体氛围压抑、神秘，具有强烈的明暗对比和低调摄影风格。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T05:29:13-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mid_90s_039.jpg","observed_dimensions":[1280,960],"source_thumbnail_dimensions":[500,375],"source_image_match_mae":0.321,"observed_resolution":"normal","observation_limits":[],"id":"VP-29549745844d6351","origin":"visual"},{"work_id":"src-078d1683967b319c","frame_id":"FG-26dd8fc1b559e7d2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Mid_90s_051.jpg","source_page":"https://film-grab.com/2019/11/08/mid90s/","scene":"一名金发年轻男子坐在车内，系着安全带，面部表情惊恐，双眼圆睁，嘴巴微张。背景是昏暗的车窗和模糊的外部灯光。","analysis":"画面主体为一名年轻男子的上半身及面部特写，占据画面中心。人物呈坐姿，身体略微前倾，安全带斜跨胸前。背景为车内环境，光线昏暗，仅有微弱的外部光源透过车窗形成模糊光斑。人物面部受光较亮，与暗背景形成对比，突显其惊恐的表情。","prompt":"一名金发年轻男子坐在汽车驾驶座或副驾驶座上，系着深色安全带，身体略微前倾。他面部表情极度惊恐，双眼圆睁，瞳孔放大，嘴巴微张露出牙齿，皮肤略显苍白且有些许瑕疵。他穿着深灰色圆领T恤。背景是昏暗的车内环境，车窗玻璃反射出模糊的外部光斑，光线主要集中在人物面部，营造出紧张、压抑的氛围。画面色调偏冷，颗粒感明显，具有胶片质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T05:29:22-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Mid_90s_051.jpg","observed_dimensions":[1280,960],"source_thumbnail_dimensions":[500,375],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-4e2ab2bd6b4711da","origin":"visual"}]};